steps.action:
curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "{
      projects(filter: { name: { eq: \"Checkout Redesign\" } }) {
        nodes {
          id
          name
          documents {
            nodes {
              id
              name
              lastEditedAt
              lastEditor {
                id
                name
              }
            }
          }
        }
      }
    }"
  }'
